fn note(i: usize, s: String) {
    S[i].diff.fetch_add(1, Ordering::Relaxed);
    let mut g = FIRST.lock().unwrap_or_else(|e| e.into_inner());
    if g.len() < FIRST_MAX && !g.iter().any(|x| x.0 == i) { g.push((i, s)); }
}

